from pathlib import Path
import sys, hashlib, re
p=Path(sys.argv[1]);html=p.read_text(encoding='utf8')
# Stable archive names otherwise allow a browser to reuse an older local build.
fingerprint=hashlib.sha256((p.parent/'archive/game0.arci').read_bytes()).hexdigest()[:16]
html=re.sub(r"<script id='galaxy-theme-archive'>.*?</script>\s*", '', html)
html=html.replace("<script id='engine-start'", f"<script id='galaxy-theme-archive'>CUSTOM_PARAMETERS.archive_location_filter = path => 'archive' + path + '?build={fingerprint}';</script>\n<script id='engine-start'")
controls='<style>body{background:#050910!important}#theme-review{position:fixed;z-index:20;top:12px;left:18px;right:18px;padding:12px 16px;border:1px solid #345263;border-radius:12px;background:#0b1a24ed;color:#bcd2df;font:13px system-ui}#theme-review button,#theme-review select{font:inherit;padding:7px 10px;margin:6px 4px 0 0;border-radius:5px;border:1px solid #426070;background:#183a4b;color:#e7f3fa}#theme-review p{margin:7px 0 0;font-size:12px;color:#91aab8}#theme-review button[aria-pressed=true]{border-color:#e2c279;background:#4c4532}</style><section id="theme-review"><strong>GALAXY / DETAILED SURFACE THEMES</strong><p>Native game models. Original / upgraded comparison. Display sizes normalized for inspection.</p><select aria-label="Ship"><option value="sardine">Sardine / patrol</option><option value="pilotfish">Pilotfish / patrol</option><option value="piranha">Piranha / patrol</option><option value="anglerfish">Anglerfish / patrol</option><option value="barracuda">Barracuda / escort</option><option value="remora">Remora / escort</option><option value="moray">Moray / escort</option><option value="lionfish">Lionfish / escort</option><option value="marlin">Marlin / frigate</option><option value="manta_ray">Manta Ray / frigate</option><option value="tiger_shark">Tiger Shark / frigate</option><option value="hammerhead">Hammerhead / frigate</option><option value="hummingbird">Hummingbird / patrol</option><option value="oxpecker">Oxpecker / patrol</option><option value="shrike">Shrike / patrol</option><option value="kingfisher">Kingfisher / patrol</option><option value="falcon">Falcon / escort</option><option value="egret">Egret / escort</option><option value="goshawk">Goshawk / escort</option><option value="osprey">Osprey / escort</option><option value="frigatebird">Frigatebird / frigate</option><option value="pelican">Pelican / frigate</option><option value="golden_eagle">Golden Eagle / frigate</option><option value="harpy_eagle">Harpy Eagle / frigate</option></select><select aria-label="Theme"><option value="porcelain_dynasty">Porcelain Dynasty</option><option value="starlight">Starlight</option><option value="grand_prix">Grand Prix</option></select><button data-command="original" aria-pressed="false">Original</button><button data-command="detail" aria-pressed="true">Upgraded</button><button data-command="front">Front</button><button data-command="rear">Rear / engines</button><button data-command="rotate">Rotate / pause</button><p id="rendered">Loading model...</p></section><script>document.querySelectorAll(\'#theme-review select\').forEach(s=>s.onchange=()=>{document.getElementById(\'rendered\').textContent=\'Loading model...\';window.galaxyThemeCommand=s.value});document.querySelectorAll(\'[data-command]\').forEach(b=>b.onclick=()=>{if([\'original\',\'detail\'].includes(b.dataset.command)){document.querySelectorAll(\'[aria-pressed]\').forEach(x=>x.setAttribute(\'aria-pressed\',String(x===b)));document.getElementById(\'rendered\').textContent=\'Loading model...\'}window.galaxyThemeCommand=b.dataset.command});</script>'
if 'id="theme-review"' not in html:html=html.replace('</body>',controls+'</body>')
p.write_text(html,encoding='utf8')
print(p)
